from enum import StrEnum
class UserStatus(StrEnum): PENDING_APPROVAL='PENDING_APPROVAL'; APPROVED='APPROVED'; REJECTED='REJECTED'; BANNED='BANNED'
class EventStatus(StrEnum): ACTIVE='ACTIVE'; CLOSED='CLOSED'
class OrderStatus(StrEnum): AWAITING_PAYMENT='AWAITING_PAYMENT'; PENDING_APPROVAL='PENDING_APPROVAL'; APPROVED='APPROVED'; REJECTED='REJECTED'; EXPIRED='EXPIRED'; CANCELED='CANCELED'
class TicketStatus(StrEnum): RESERVED='RESERVED'; ISSUED='ISSUED'; USED='USED'; REFUND_PENDING='REFUND_PENDING'; CANCELED='CANCELED'
class RefundStatus(StrEnum): PENDING='PENDING'; APPROVED='APPROVED'; REJECTED='REJECTED'
class SupportStatus(StrEnum): OPEN='OPEN'; CLOSED='CLOSED'
class PromoReservationStatus(StrEnum): RESERVED='RESERVED'; CONSUMED='CONSUMED'; RELEASED='RELEASED'
class WalletEntryType(StrEnum): REFUND_CREDIT='REFUND_CREDIT'; PURCHASE_DEBIT='PURCHASE_DEBIT'; WITHDRAWAL_LOCK='WITHDRAWAL_LOCK'; WITHDRAWAL_PAID='WITHDRAWAL_PAID'; WITHDRAWAL_RELEASE='WITHDRAWAL_RELEASE'; ADMIN_ADJUSTMENT='ADMIN_ADJUSTMENT'
class WithdrawalStatus(StrEnum): PENDING='PENDING'; PAID='PAID'; REJECTED='REJECTED'; CANCELED='CANCELED'
class WaitlistStatus(StrEnum): WAITING='WAITING'; NOTIFIED='NOTIFIED'; CONVERTED='CONVERTED'; CANCELED='CANCELED'; EXPIRED='EXPIRED'
class NotificationStatus(StrEnum): PENDING='PENDING'; SENT='SENT'; FAILED='FAILED'
